        )
    elif errors:
        print(f"INVALID: {target}", file=sys.stderr)
        for error in errors:
            print(f"- {error}", file=sys.stderr)
    else:
        print(f"VALID: {target}")
    return 1 if errors else 0


if __name__ == "__main__":
